// Generated by `setu new --workspace`. Starts every service in this workspace,
// waiting for each declared prerequisite's `/ready` endpoint before starting the
// services that depend on it. Prerequisites come from the `dependsOn` list in
// setu.workspace.json, which `setu generate app --depends-on` records.

import { readFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';

const manifest = JSON.parse(await readFile('setu.workspace.json', 'utf8'));
const members = new Map(manifest.members.map((member) => [member.name, member]));
// The launcher selects exactly one development entry and owns its process group.
const devtoolSelectedName = process.env['SETU_DEVTOOL_MEMBER'];
const devtoolSessionId = process.env['SETU_DEVTOOL_SESSION_ID'];
const devtoolSessionKey = process.env['SETU_DEVTOOL_SESSION_KEY'];
let devtoolSelected;
if (devtoolSelectedName !== undefined && devtoolSelectedName !== '') {
  const named = members.get(devtoolSelectedName);
  if (named === undefined) {
    throw new Error(
      `SETU_DEVTOOL_MEMBER names "${devtoolSelectedName}", which setu.workspace.json ` +
        `does not carry. Members: ${[...members.keys()].join(', ')}.`,
    );
  }
  if (named.devtoolPort === undefined) {
    throw new Error(
      `SETU_DEVTOOL_MEMBER names "${devtoolSelectedName}", but that member carries no ` +
        `devtoolPort. Run npx @setu-ts/cli@0.11.0 devtool enable ${devtoolSelectedName} first.`,
    );
  }
  devtoolSelected = named;
}

const childEnv = (member) => {
  const selected = devtoolSelected !== undefined && devtoolSelected.name === member.name;
  return {
    ...process.env,
    SETU_DEVTOOL_MEMBER: selected ? (devtoolSelectedName ?? '') : '',
    SETU_DEVTOOL_SESSION_ID: selected ? (devtoolSessionId ?? '') : '',
    SETU_DEVTOOL_SESSION_KEY: selected ? (devtoolSessionKey ?? '') : '',
  };
};

const entryTask = (member) =>
  devtoolSelected !== undefined && devtoolSelected.name === member.name ? 'dev' : 'start:dev';

const started = new Set();
const visiting = new Set();
const children = [];

const pause = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));

// Without a selection each member owns a process group (POSIX); under selection
// the launcher owns the whole group, so no child may detach from it.
// Shutdown signals each owned group or direct child:
// the package manager runs `start` through a shell, and a shell that does not forward the
// signal (dash, as on Ubuntu) would otherwise leave the server running, holding its port.
const grouped = process.platform !== 'win32' && devtoolSelected === undefined;

const shutdown = () => {
  for (const child of children) {
    try {
      if (grouped) process.kill(-child.pid, 'SIGTERM');
      else child.kill('SIGTERM');
    } catch {
      // Already gone: a child that exited on its own has nothing to signal.
    }
  }
};

async function waitForReady(member) {
  const deadline = performance.now() + 30_000;
  while (performance.now() < deadline) {
    try {
      if ((await fetch(`http://127.0.0.1:${member.port}/ready`)).ok) return;
    } catch {
      // Not listening yet: keep polling until the deadline.
    }
    await pause(100);
  }
  throw new Error(`Dependency "${member.name}" did not become ready within 30 seconds.`);
}

async function start(member) {
  if (started.has(member.name)) return;
  if (visiting.has(member.name)) {
    throw new Error(`Dependency cycle includes "${member.name}".`);
  }
  visiting.add(member.name);
  for (const name of member.dependsOn ?? []) {
    const dependency = members.get(name);
    if (dependency === undefined) {
      throw new Error(`Unknown dependency "${name}" for "${member.name}".`);
    }
    await start(dependency);
    await waitForReady(dependency);
  }
  visiting.delete(member.name);
  const child = spawn('npm', ['run', entryTask(member)], {
    cwd: `apps/${member.name}`,
    stdio: 'inherit',
    env: childEnv(member),
    detached: grouped,
  });
  children.push(child);
  started.add(member.name);
  child.once('exit', (code) => {
    if (code !== 0) {
      // A failed member breaks its dependents; keep that failure visible.
      shutdown();
      process.exitCode = code ?? 1;
    }
  });
}

// Registered before the first child, so an interrupt DURING startup — which can
// last as long as the readiness deadline — still takes the children with it.
process.on('SIGINT', () => {
  shutdown();
  process.exit();
});
process.on('SIGTERM', () => {
  shutdown();
  process.exit();
});

try {
  for (const member of manifest.members) await start(member);
} catch (cause) {
  shutdown();
  throw cause;
}
